462: async function roleMovement(aiTok, targetTok, pcs, role, moveFeet) {
463:   if (role === "sniper") {
464:     // Sniper tries to keep distance: if too close (<20), back away; else minimal move.
465:     const d = dist(aiTok, targetTok);
466:     if (d < 20) return retreat(aiTok, pcs, moveFeet);
467:     if (d > 60) return moveToward(aiTok, targetTok, moveFeet); // close slightly if too far
468:     return; // hold position
469:   }
470:   if (role === "coward") {
471:     // Coward prefers distance; move away if anyone is within 25
472:     const nearest = nearestToken(aiTok, pcs);
473:     if (nearest && dist(aiTok, nearest) < 25) return retreat(aiTok, pcs, moveFeet);
474:     // otherwise take a potshot if it has one; we still allow a small adjust
475:     return;
476:   }
477:   // Brute/controller/caster/boss: close in
478:   return moveToward(aiTok, targetTok, moveFeet);
479: }
