481: function nearestToken(aiTok, toks) {
482:   let best = null; let bd = 1e9;
483:   for (const t of toks) {
484:     const d = dist(aiTok, t);
485:     if (d < bd) { bd = d; best = t; }
486:   }
487:   return best;
488: }
