490: async function moveToward(aiTok, targetTok, maxFeet) {
491:   const start = aiTok.center;
492:   const end = targetTok.center;
493:   const total = gridDistanceFeet(start, end);
494:   if (!total || total <= 5) return;
495: 
496:   const step = Math.min(maxFeet, Math.max(0, total - 5));
497:   if (step <= 0) return;
498: 
499:   const ratio = step / total;
500:   const nx = start.x + (end.x - start.x) * ratio;
501:   const ny = start.y + (end.y - start.y) * ratio;
502: 
503:   const snapped = canvas.grid.getSnappedPosition(nx - aiTok.w/2, ny - aiTok.h/2, 1);
504:   await aiTok.document.update({ x: snapped.x, y: snapped.y }, { animate: true });
505: }
