507: async function retreat(aiTok, pcs, maxFeet) {
508:   // Move away from the nearest PC (simple vector away)
509:   const nearest = nearestToken(aiTok, pcs);
510:   if (!nearest) return;
511: 
512:   const start = aiTok.center;
513:   const from = nearest.center;
514: 
515:   const vx = start.x - from.x;
516:   const vy = start.y - from.y;
517:   const mag = Math.hypot(vx, vy) || 1;
518: 
519:   // Move maxFeet along that vector
520:   const step = maxFeet;
521:   const nx = start.x + (vx / mag) * step;
522:   const ny = start.y + (vy / mag) * step;
523: 
524:   const snapped = canvas.grid.getSnappedPosition(nx - aiTok.w/2, ny - aiTok.h/2, 1);
525:   await aiTok.document.update({ x: snapped.x, y: snapped.y }, { animate: true });
526: }
