528: function gridDistanceFeet(p1, p2) {
529:   try {
530:     const r = new Ray(p1, p2);
531:     const d = canvas.grid.measureDistances([{ ray: r }], { gridSpaces: true })?.[0];
532:     return Number(d) || 0;
533:   } catch (e) { return 0; }
534: }
