558: /* ---------------- MORALE ---------------- */
559: function evaluateMoraleRetreat(actor, aiTok, pcs, cfg, combat) {
560:   const role = cfg.role ?? defaultRole();
561:   const moraleBase = clamp01(cfg.morale ?? 0.6);
562:   const hp = getHPpct(actor);
563: 
564:   // Ally losses in this combat: count NPCs on same side that are at 0 HP.
565:   // We approximate: other npc combatants with enabled AI are "allies".
566:   let allyDown = 0, allyTotal = 0;
567:   try {
568:     const comb = combat ?? game.combat;
569:     const allies = comb?.combatants?.filter(cb => cb.actor?.type === "npc" && cb.actor?.id !== actor.id) ?? [];
570:     for (const a of allies) {
571:       allyTotal++;
572:       const ahp = a.actor.system?.attributes?.hp?.value ?? 1;
573:       if (ahp <= 0) allyDown++;
574:     }
575:   } catch (e) {}
576: 
577:   const allyLoss = allyTotal ? (allyDown / allyTotal) : 0;
578: 
579:   // Pressure: low HP + ally loss + role disposition
580:   let cowardice = 0;
581:   if (role === "coward") cowardice += 0.35;
582:   if (role === "sniper") cowardice += 0.10;
583:   if (role === "boss") cowardice -= 0.25; // bosses resist retreat
584:   if (role === "brute") cowardice -= 0.10;
585: 
586:   const pressure = clamp01((1 - hp) * 0.6 + allyLoss * 0.4);
587:   // Retreat if pressure exceeds morale (adjusted)
588:   const threshold = clamp01(moraleBase + (-cowardice));
589:   // Add a small randomness so it's not deterministic
590:   const roll = Math.random() * 0.15;
591:   return (pressure + roll) > threshold;
592: }
